// Parse and aggregate all agent outputs
const responses = $input.all();
const outputs = {};

responses.forEach((resp, idx) => {
  const content = resp.json.content[0].text;
  outputs[`agent${idx + 1}`] = content;
});

return {
  agent1: outputs.agent1 || '',
  agent2: outputs.agent2 || '',
  agent3: outputs.agent3 || '',
  agent4: outputs.agent4 || '',
  agent5: outputs.agent5 || '',
  agent6: outputs.agent6 || '',
  agent7: outputs.agent7 || '',
  agent8: outputs.agent8 || '',
  timestamp: new Date().toISOString(),
  status: 'aggregated'
};

// Generate markdown files and master document
const docs = $input.all()[0].json;

const files = {
  '01-Market-Research.md': docs.agent1,
  '02-Regulatory-Compliance.md': docs.agent2,
  '03-Market-Entry-Strategy.md': docs.agent3,
  '04-Competitive-Analysis.md': docs.agent4,
  '05-GTM-Plan.md': docs.agent5,
  '06-Financial-Projections.md': docs.agent6,
  '07-Risk-Management.md': docs.agent7,
  '08-Implementation-Roadmap.md': docs.agent8
};

const masterDoc = `# India Launch Playbook - Complete Guide

*Generated on ${docs.timestamp}*

## Table of Contents
1. Market Research & Insights
2. Regulatory & Compliance Framework
3. Market Entry Strategy
4. Competitive Landscape Analysis
5. Go-To-Market Plan
6. Financial Projections & Pricing
7. Risk Management & Contingencies
8. Implementation Roadmap

---

## 📊 Package Information
- **Generated**: ${docs.timestamp}
- **Total Documents**: 8
- **Total Lines**: ${Object.values(files).reduce((sum, doc) => sum + (doc ? doc.split('\n').length : 0), 0)}
- **Status**: Complete

---

${Object.values(files).join('\n\n---\n\n')}`;

return {
  files,
  masterDoc,
  metadata: {
    timestamp: docs.timestamp,
    documentCount: Object.keys(files).length,
    totalLines: Object.values(files).reduce((sum, doc) => sum + (doc ? doc.split('\n').length : 0), 0),
    averageLinesPerDoc: Math.round(Object.values(files).reduce((sum, doc) => sum + (doc ? doc.split('\n').length : 0), 0) / Object.keys(files).length)
  }
};
